(function($){
    // Minimal JS to handle file input upload, show progress, notify on completion
    // and immediately add the uploaded file to the files list without page refresh.
    // This file expects an input element with id="project_file_input" and a
    // file list table with id="project-files-table" (tbody available).

    function showToast(type, message) {
        // Try to use Perfex alert_float if available, fallback to simple alert
        if (typeof(alert_float) === 'function') {
            alert_float(type, message);
            return;
        }
        if (type === 'success') {
            try { console.info(message); } catch (e) {}
            alert(message);
        } else {
            try { console.error(message); } catch (e) {}
            alert(message);
        }
    }

    $(document).on('change', '#project_file_input', function(e){
        var fileInput = this;
        var file = fileInput.files && fileInput.files[0];
        if (!file) return;

        var projectId = $(fileInput).data('project-id');
        var formData = new FormData();
        formData.append('file', file);
        if (typeof projectId !== 'undefined') {
            formData.append('project_id', projectId);
        }

        // Create minimal progress UI element
        var $progressWrap = $('<div class="pc-upload-progress" style="width:100%;border:1px solid #ddd;padding:4px;margin:8px 0;background:#f7f7f7;"></div>');
        var $bar = $('<div style="width:0%;height:18px;background:#2ecc71;color:#fff;text-align:center;font-size:12px;">0%</div>');
        $progressWrap.append($bar);
        $(fileInput).after($progressWrap);

        $.ajax({
            url: admin_url + 'projects/upload_file',
            type: 'POST',
            data: formData,
            processData: false,
            contentType: false,
            xhr: function() {
                var xhr = new XMLHttpRequest();
                xhr.upload.addEventListener('progress', function(evt) {
                    if (evt.lengthComputable) {
                        var percentComplete = Math.round((evt.loaded / evt.total) * 100);
                        $bar.css('width', percentComplete + '%');
                        $bar.text(percentComplete + '%');
                    }
                }, false);
                return xhr;
            },
            success: function(response) {
                var res = response;
                if (typeof response === 'string') {
                    try { res = JSON.parse(response); } catch (e) { res = { success: false, error: 'Invalid server response' }; }
                }

                if (res && res.success) {
                    // Notify user upload complete
                    showToast('success', 'Upload complete');

                    // Remove progress UI
                    $progressWrap.remove();

                    // Ensure the file list exists and append the returned file item.
                    var fileData = res.file || {};
                    var fileId = fileData.id || '';
                    var fileName = fileData.file_name || file.name;
                    var filePath = fileData.file_path || '';

                    var $row = $(
                        '<tr id="project-file-' + (fileId ? fileId : fileName.replace(/[^a-z0-9\.\-_]/ig, '_')) + '">' +
                            '<td>' + $('<div/>').text(fileName).html() + '</td>' +
                            '<td>' +
                                (fileId ? '<a href="' + admin_url + 'projects/download_file/' + fileId + '">Download</a>' : '<a href="/' + filePath + '" target="_blank">Download</a>') +
                            '</td>' +
                        '</tr>'
                    );

                    var $tableBody = $('#project-files-table tbody');
                    if ($tableBody.length === 0) {
                        // If table body not found, try to append to table
                        var $table = $('#project-files-table');
                        if ($table.length) {
                            $table.append($row);
                        }
                    } else {
                        $tableBody.prepend($row);
                    }

                } else {
                    showToast('danger', res.error || 'Upload failed');
                    $progressWrap.remove();
                }
            },
            error: function() {
                showToast('danger', 'Upload failed');
                $progressWrap.remove();
            }
        });

        // Clear the input so the same filename can be selected again if needed
        $(fileInput).val('');
    });
})(jQuery);
